// Fixed-step causal model. Presentation never decides outcomes.
export const W=36,H=26,DAY=1440,VERSION=3;
export const DEFAULTS={hungerRate:.05,moveCost:.18,restGain:.7,regenA:.18,regenB:.16,perception:4,learning:.005,exploration:8,policy:'scored',starveTicks:300,moveEvery:4,expectationRate:.35,revealPrior:60};
export const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
export function noise(seed,t,id,salt=0){let n=(seed^Math.imul(t+1,374761393)^Math.imul(id+1,668265263)^Math.imul(salt+1,1274126177))>>>0;n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296;}
export function land(x,y,bridge=false){return x>=0&&y>=0&&x<W&&y<H&&((x-17.5)/16)**2+((y-12.5)/11)**2<=1&&(!(x===18&&y>=4&&y<=20)||(bridge&&y===13));}
export function seedKey(seed){let h=(seed^0x9e3779b9)>>>0;h=Math.imul(h^(h>>>16),0x85ebca6b);h=Math.imul(h^(h>>>13),0xc2b2ae35);return(h^(h>>>16))>>>0;}
const fmix=h=>{h=Math.imul(h^(h>>>16),0x85ebca6b);h=Math.imul(h^(h>>>13),0xc2b2ae35);return(h^(h>>>16))>>>0;};
export function noise2(key,t,id,salt=0){let h=fmix(key^Math.imul(t+1,0x9e3779b1));h=fmix(h^Math.imul(id+1,0x85ebca77));h=fmix(h^Math.imul(salt+1,0xc2b2ae3d));return h/4294967296;}
const draw=(s,t,id,salt)=>s.rng===2?noise2(seedKey(s.seed),t,id,salt):noise(s.seed,t,id,salt);
const cache=new Map();
export function path(x,y,tx,ty,bridge){const key=[x,y,tx,ty,+bridge].join(',');if(cache.has(key))return cache.get(key).map(p=>[...p]);let q=[[x,y]],prev=new Map([[y*W+x,-1]]);for(let i=0;i<q.length;i++){const[a,b]=q[i];if(a===tx&&b===ty)break;for(const[nx,ny]of[[a+1,b],[a-1,b],[a,b+1],[a,b-1]])if(land(nx,ny,bridge)&&!prev.has(ny*W+nx)){prev.set(ny*W+nx,b*W+a);q.push([nx,ny]);}}let out=[],end=ty*W+tx;if(prev.has(end))for(let n=end;prev.get(n)!==-1;n=prev.get(n))out.push([n%W,Math.floor(n/W)]);out.reverse();if(cache.size>20000)cache.clear();cache.set(key,out);return out.map(p=>[...p]);}
const names=['Neri','Oru','Tavi','Milo','Ena','Pip','Koa','Lumi','Sora','Ivo','Una','Remi','Ari','Nima','Teo','Fia','Omi','Runa','Sol','Zia','Lio','Mara','Nori','Ava'];
export function createWorld(seed=41,overrides={}){const k=seedKey(seed>>>0),s={version:VERSION,seed:seed>>>0,rng:2,tick:0,config:{...DEFAULTS,...overrides},bridge:false,patches:[{id:'a',name:'Berry grove',x:10,y:9,stock:120,capacity:120,regen:overrides.regenA??DEFAULTS.regenA,gift:false},{id:'b',name:'Root garden',x:27,y:15,stock:120,capacity:120,regen:overrides.regenB??DEFAULTS.regenB,gift:false}],creatures:[],ledger:{initial:240,regenerated:0,gifted:0,consumed:0},events:[],commands:[],digest:0};for(let id=0;id<24;id++)s.creatures.push({id,name:names[id],x:7+Math.floor(noise2(k,0,id)*8),y:8+Math.floor(noise2(k,0,id,1)*9),alive:true,hunger:20,energy:80,starving:0,known:{},skills:{a:0,b:0},visited:{},action:null,decision:null,memories:[],consumed:0,giftConsumed:0,times:{travel:0,gather:0,rest:0,explore:0},death:null});event(s,'The island begins. 24 lives, two food sources.');return s;}
export function event(s,text,c){s.digest=(Math.imul(s.digest,31)+s.tick+text.length+(c?.id??0))>>>0;const arr=c?c.memories:s.events;arr.push({tick:s.tick,text});if(arr.length>(c?12:100))arr.shift();}
export function command(s,cmd){const c=s.creatures.find(c=>c.id===cmd.id);if(cmd.type==='food'){const amount=cmd.amount??40;if(!Number.isInteger(cmd.x)||!Number.isInteger(cmd.y)||!land(cmd.x,cmd.y,s.bridge))throw Error('Choose dry land.');if(!Number.isFinite(amount)||amount<=0||amount>200)throw Error('Invalid amount');let p=s.patches.find(p=>p.gift&&p.x===cmd.x&&p.y===cmd.y);if(!p){if(s.patches.length>=100)throw Error('Placement limit reached');p={id:'g'+s.patches.length,name:'Gifted food',x:cmd.x,y:cmd.y,stock:0,capacity:10000,regen:0,gift:true};s.patches.push(p);}if(p.stock+amount>p.capacity)throw Error('Food pile is full');p.stock+=amount;s.ledger.gifted+=amount;event(s,`You provided ${amount} food at ${cmd.x}, ${cmd.y}.`);}else if(cmd.type==='bridge'){s.bridge=true;for(const c of s.creatures)if(c.action?.route?.length)c.action=null;event(s,'Crossing opened. Routes change; knowledge does not.');}else if(cmd.type==='reveal'){if(!c?.alive)throw Error('Select a living creature');const p=s.patches.find(p=>p.id===(cmd.patch??'b'));if(!p)throw Error('Unknown source');if(c.known[p.id])event(s,`${c.name} already knew where ${p.name} is; nothing changed.`);else{c.known[p.id]={expected:s.config.revealPrior,last:s.tick};c.action=null;event(s,`${p.name} revealed to ${c.name} only.`);event(s,`Learned where ${p.name} is. Stock unknown.`,c);}}else if(cmd.type==='failure'){const p=s.patches.find(p=>!p.gift&&p.id===(cmd.patch??'a'));if(!p)throw Error('Unknown source');p.regen=0;event(s,`Experiment: ${p.name} regeneration stopped; existing stock retained.`);}else throw Error('Unknown command');s.commands.push({tick:s.tick,...cmd});}
export function observe(s,c){c.visited[c.y*W+c.x]=true;for(const p of s.patches)if(Math.abs(p.x-c.x)+Math.abs(p.y-c.y)<=s.config.perception){if(!c.known[p.id])event(s,`Discovered ${p.name}.`,c);const k=c.known[p.id];c.known[p.id]={expected:k?k.expected*(1-s.config.expectationRate)+p.stock*s.config.expectationRate:p.stock,last:s.tick};}}
function explore(s,c){let best=[c.x,c.y],score=-Infinity;for(let i=0;i<18;i++){const x=2+Math.floor(draw(s,s.tick,c.id,10+i)*32),y=2+Math.floor(draw(s,s.tick,c.id,40+i)*22);if(!land(x,y,s.bridge))continue;const v=(c.visited[y*W+x]?0:30)-Math.abs(c.x-x)-Math.abs(c.y-y);if(v>score){score=v;best=[x,y];}}return best;}
export function decide(s,c){let options=[{type:'rest',score:(100-c.energy)*.48-12,reason:'Recover energy; hunger continues.'},{type:'explore',score:s.config.exploration*(.4+c.energy/100),reason:'Seek unvisited ground.'}];for(const p of s.patches){const k=c.known[p.id];if(!k)continue;const route=path(c.x,c.y,p.x,p.y,s.bridge);if(!route.length&&(c.x!==p.x||c.y!==p.y))continue;options.push({type:'gather',patch:p.id,route,score:(c.hunger-8)*Math.min(1,Math.max(.08,k.expected/8))-route.length*.35+(c.skills[p.id]??0)*2,reason:`Expected food ${k.expected.toFixed(1)} · ${route.length} tiles away · skill ${Math.round((c.skills[p.id]??0)*100)}%`});}let choice;if(c.energy<10)choice=options[0];else if(s.config.policy==='rule')choice=(c.hunger>28?options.filter(o=>o.type==='gather').sort((a,b)=>b.score-a.score)[0]:null)??(c.energy<45?options[0]:options[1]);else choice=[...options].sort((a,b)=>b.score-a.score)[0];c.decision={tick:s.tick,hunger:c.hunger,energy:c.energy,selected:choice.type,patch:choice.patch??null,policy:s.config.policy,emergency:c.energy<10,options:options.map(({route,...v})=>v)};if(choice.type==='rest')c.action={type:'rest',left:28};else if(choice.type==='explore'){const[x,y]=explore(s,c);c.action={type:'explore',route:path(c.x,c.y,x,y,s.bridge)};}else c.action={type:'gather',patch:choice.patch,route:choice.route,left:Math.max(4,Math.round(14-8*(c.skills[choice.patch]??0)))};}
export function step(s,n=1){for(let z=0;z<n;z++){s.tick++;for(const p of s.patches){const add=Math.max(0,Math.min(p.regen,p.capacity-p.stock));p.stock+=add;s.ledger.regenerated+=add;}const order=s.creatures.filter(c=>c.alive).sort((a,b)=>draw(s,s.tick,a.id,99)-draw(s,s.tick,b.id,99));for(const c of order)observe(s,c);for(const c of order)if(!c.action||(c.energy<5&&c.action.type!=='rest'))decide(s,c);for(const c of order){const a=c.action;c.hunger=clamp(c.hunger+s.config.hungerRate);if(a.type==='rest'){c.times.rest++;c.energy=clamp(c.energy+s.config.restGain);if(--a.left<=0)c.action=null;}else if(a.route.length){c.times[a.type==='explore'?'explore':'travel']++;if(s.tick%s.config.moveEvery===0){[c.x,c.y]=a.route.shift();c.energy=clamp(c.energy-s.config.moveCost);}if(!a.route.length&&a.type==='explore')c.action=null;}else if(a.type==='explore')c.action=null;else{c.times.gather++;if(--a.left<=0){const p=s.patches.find(p=>p.id===a.patch),take=Math.min(p.stock,4);p.stock-=take;s.ledger.consumed+=take;c.consumed+=take;if(p.gift)c.giftConsumed+=take;c.hunger=clamp(c.hunger-take*4);c.energy=clamp(c.energy+take*2);if(take>0&&!p.gift)c.skills[p.id]=Math.min(1,(c.skills[p.id]??0)+s.config.learning*take/4);c.known[p.id]={expected:p.stock,last:s.tick};event(s,take?`Ate ${take.toFixed(1)} from ${p.name}.`:`Found ${p.name} empty.`,c);c.action=null;}}c.starving=c.hunger>=99?c.starving+1:0;if(c.starving>=s.config.starveTicks){c.alive=false;c.death={tick:s.tick,cause:'Sustained food deprivation'};c.action=null;event(s,`${c.name} died from sustained food deprivation.`);}}}return s;}
export function metrics(s){const a=s.creatures.filter(c=>c.alive);const med=v=>{v.sort((x,y)=>x-y);return v.length?(v[Math.floor((v.length-1)/2)]+v[Math.ceil((v.length-1)/2)])/2:null;};return {tick:s.tick,alive:a.length,medianHunger:med(a.map(c=>c.hunger)),medianHungerAll:med(s.creatures.map(c=>c.alive?c.hunger:100)),deaths:s.creatures.length-a.length,medianEnergy:med(a.map(c=>c.energy)),knownSources:a.length?a.reduce((n,c)=>n+['a','b'].filter(k=>c.known[k]).length,0)/a.length:0,skill:a.length?a.reduce((n,c)=>n+c.skills.a+c.skills.b,0)/(a.length*2):0,knownSourcesAll:a.reduce((n,c)=>n+['a','b'].filter(k=>c.known[k]).length,0)/s.creatures.length,skillAll:a.reduce((n,c)=>n+c.skills.a+c.skills.b,0)/(s.creatures.length*2),food:s.patches.reduce((n,p)=>n+p.stock,0),giftRemaining:s.patches.reduce((n,p)=>n+(p.gift?p.stock:0),0),gifted:s.ledger.gifted,consumed:s.ledger.consumed,individuals:s.creatures.map(c=>({id:c.id,name:c.name,alive:c.alive,hunger:c.hunger,energy:c.energy,knownSources:['a','b'].filter(k=>c.known[k]).length,skills:{...c.skills},consumed:c.consumed,giftConsumed:c.giftConsumed,times:{...c.times},death:c.death}))};}
export function serialize(s){return JSON.stringify({format:'island-save',version:VERSION,world:s});}
export function deserialize(text){if(text.length>5000000)throw Error('Save too large');let e;try{e=JSON.parse(text);}catch{throw Error('Invalid JSON save');}const s=e?.world;const num=(v,a=0,b=1e10)=>typeof v==='number'&&Number.isFinite(v)&&v>=a&&v<=b;const xy=(x,y)=>Number.isInteger(x)&&Number.isInteger(y)&&land(x,y,s.bridge);const fail=()=>{throw Error('Invalid or incompatible save');};if(e?.format!=='island-save'||![2,VERSION].includes(e.version)||s?.version!==e.version)fail();if(e.version===2&&s.config&&typeof s.config==='object'){s.config={...s.config,expectationRate:s.config.expectationRate??DEFAULTS.expectationRate,revealPrior:s.config.revealPrior??DEFAULTS.revealPrior};s.version=VERSION;}if(!Number.isInteger(s.seed)||(s.rng!==undefined&&s.rng!==1&&s.rng!==2)||!num(s.tick)||!Number.isInteger(s.tick)||typeof s.bridge!=='boolean'||!Array.isArray(s.creatures)||s.creatures.length!==24||!Array.isArray(s.patches)||s.patches.length<2||s.patches.length>100)fail();for(const k of Object.keys(DEFAULTS))if(k==='policy'?!['scored','rule'].includes(s.config?.[k]):!num(s.config?.[k],0,10000))fail();if(!Number.isInteger(s.config.moveEvery)||s.config.moveEvery<1||s.config.starveTicks<1||s.config.expectationRate>1)fail();const ids=new Set();for(const p of s.patches){if(typeof p.id!=='string'||!/^([ab]|g\d+)$/.test(p.id)||ids.has(p.id)||!xy(p.x,p.y)||!num(p.stock,0,1e7)||!num(p.capacity,1,1e7)||p.stock>p.capacity||!num(p.regen)||typeof p.gift!=='boolean'||typeof p.name!=='string'||p.name.length>80)fail();ids.add(p.id);}if(!ids.has('a')||!ids.has('b'))fail();for(const[i,c]of s.creatures.entries()){if(c.id!==i||typeof c.name!=='string'||c.name.length>40||!xy(c.x,c.y)||typeof c.alive!=='boolean'||!num(c.hunger,0,100)||!num(c.energy,0,100)||!num(c.starving)||!c.known||!c.skills||!c.visited||Object.keys(c.visited).length>W*H||!Array.isArray(c.memories)||c.memories.length>12)fail();for(const[k,v]of Object.entries(c.known))if(!ids.has(k)||!num(v.expected)||!num(v.last,0,s.tick))fail();for(const k of ['a','b'])if(!num(c.skills[k],0,1))fail();for(const k of ['travel','gather','rest','explore'])if(!num(c.times?.[k]))fail();if(!num(c.consumed)||!num(c.giftConsumed)||c.giftConsumed>c.consumed)fail();if(c.alive?c.death!=null:(!num(c.death?.tick,0,s.tick)||typeof c.death.cause!=='string'||c.death.cause.length>200))fail();const acts=['rest','explore','gather'],d=c.decision;if(d&&(!num(d.tick,0,s.tick)||!num(d.hunger,0,100)||!num(d.energy,0,100)||!acts.includes(d.selected)||(d.patch!==null&&!ids.has(d.patch))||(Array.isArray(d.options)&&d.options.some(o=>!acts.includes(o?.type)||(o.patch!==undefined&&!ids.has(o.patch))))))fail();const a=c.action;if(a){if(!['rest','explore','gather'].includes(a.type))fail();if(a.type!=='rest'&&(!Array.isArray(a.route)||a.route.length>W*H||a.route.some(p=>!Array.isArray(p)||!xy(p[0],p[1]))))fail();if(a.type==='gather'&&!ids.has(a.patch))fail();if(a.type!=='explore'&&!num(a.left))fail();}if(c.decision&&(!Array.isArray(c.decision.options)||c.decision.options.length>102||c.decision.options.some(o=>!num(o.score,-1e6,1e6)||typeof o.reason!=='string')))fail();}for(const k of ['initial','regenerated','gifted','consumed'])if(!num(s.ledger?.[k],0,1e12))fail();if(!Array.isArray(s.events)||s.events.length>100||!Array.isArray(s.commands)||s.commands.length>100000)fail();for(const v of [...s.events,...s.creatures.flatMap(c=>c.memories)])if(typeof v.text!=='string'||v.text.length>500||!num(v.tick,0,s.tick))fail();if(Math.abs(s.ledger.initial+s.ledger.regenerated+s.ledger.gifted-s.ledger.consumed-s.patches.reduce((n,p)=>n+p.stock,0))>.001)fail();return s;}
